import { parentPort } from "node:worker_threads";
import { startWorkerHost } from "./host.js";
const port = parentPort;
if (!port)
    throw new Error("Lix worker requires a parent port");
startWorkerHost({
    postMessage(message) {
        port.postMessage(message);
    },
    onMessage(listener) {
        port.on("message", (message) => listener(message));
    },
});
